for caption, paragraph in additions.items():
    needle = caption + "\n"
    replacement = caption + "\n\n" + paragraph + "\n"
    if needle in text and replacement not in text:
        text = text.replace(needle, replacement, 1)

path.write_text(text, encoding="utf-8")
print(path)
